<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Factory Traffic Control</title>
    <style>
        :root{--ink:#17221f;--muted:#69736e;--paper:#f5f2e9;--panel:#fffdf8;--line:#d9d6c9;--green:#2b9b69;--red:#d9574d;--yellow:#d39c32;--teal:#0b7775}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 85% 0,#dceee4,transparent 35%),var(--paper);color:var(--ink);font:15px/1.45 Georgia,serif}main{max-width:1180px;margin:auto;padding:28px 20px 60px}header{display:flex;justify-content:space-between;align-items:end;border-bottom:2px solid var(--ink);padding-bottom:16px}h1,h2,p{margin:0}h1{font-size:clamp(2rem,5vw,4rem);letter-spacing:-.04em}h2{font-size:1.1rem;margin-bottom:12px}.eyebrow,.label{font:700 .72rem/1.2 ui-sans-serif,sans-serif;letter-spacing:.12em;text-transform:uppercase}.eyebrow{color:var(--teal)}.stamp{color:var(--muted);font:12px ui-monospace,monospace}.error{display:none;background:#ffe1dd;border:1px solid #d9574d;padding:11px;margin:16px 0;font:700 13px ui-sans-serif,sans-serif}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:18px;margin-top:22px}.panel{background:color-mix(in srgb,var(--panel) 90%,transparent);border:1px solid var(--line);padding:20px;box-shadow:6px 6px 0 #dfe6dd}.wide{grid-column:1/-1}.summary{display:flex;gap:20px;flex-wrap:wrap;align-items:center}.badge{display:inline-block;padding:5px 9px;border-radius:3px;background:#dceee4;color:#176147;font:700 12px ui-sans-serif,sans-serif}.badge.warn{background:#ffe1dd;color:#9c3028}.banner{padding:10px;margin:12px 0;background:#fff0c9;border-left:4px solid var(--yellow);font-weight:bold}.banner:empty{display:none}.signals{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:20px auto;max-width:480px}.signal{border:1px solid var(--line);padding:12px;display:flex;align-items:center;gap:10px;background:#faf8f1}.lamp{width:28px;height:28px;border-radius:50%;background:#b5b8af;border:3px solid #fff;box-shadow:0 0 0 1px #aaa}.lamp.GREEN{background:var(--green)}.lamp.YELLOW{background:var(--yellow)}.lamp.RED{background:var(--red)}.lamp.UNKNOWN{background:#59615e}.signal small{display:block;color:var(--muted);font:11px ui-monospace,monospace}.mismatch{outline:2px solid var(--yellow)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.stat{padding:12px;background:#edf1e8}.stat strong{display:block;font-size:1.6rem}.stat span{color:var(--muted);font-size:12px}.controls{display:flex;flex-wrap:wrap;gap:8px}button,select,input{font:inherit;border:1px solid var(--ink);padding:9px;background:var(--panel);color:var(--ink)}button{cursor:pointer;background:var(--ink);color:white}button.secondary{background:var(--panel);color:var(--ink)}form{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}form label{display:grid;gap:4px;font:12px ui-sans-serif,sans-serif;color:var(--muted)}form button{grid-column:1/-1}.activity{list-style:none;padding:0;margin:0;max-height:270px;overflow:auto}.activity li{border-bottom:1px solid var(--line);padding:9px 0;font-size:13px}.activity time{float:right;color:var(--muted);font:11px ui-monospace,monospace}@media(max-width:760px){.grid{grid-template-columns:1fr}.wide{grid-column:auto}.stats{grid-template-columns:repeat(2,1fr)}form{grid-template-columns:1fr 1fr}header{display:block}.stamp{margin-top:8px}}
    </style>
</head>
<body>
<main>
    <header><div><div class="eyebrow">Factory traffic / live operations</div><h1 id="title">Junction A</h1></div><div class="stamp" id="updated">Connecting...</div></header>
    <div class="error" id="error" role="alert"></div>
    <section class="grid">
        <article class="panel"><div class="summary"><h2>Intersection state</h2><span class="badge" id="mode">--</span><span id="phase">--</span></div><div id="banners"><div class="banner" id="emergency"></div><div class="banner" id="manual"></div></div><div class="signals" id="signals"></div><div class="stats" id="queues"></div></article>
        <article class="panel"><h2>Controller</h2><p>status: <strong id="controller">--</strong></p><p>pending command: <code id="pending">none</code></p><p>alerts: <span id="alerts">none</span></p><hr><h2>Manual control</h2><div class="controls"><button data-command="GREEN_NS">Green N/S</button><button data-command="GREEN_EW">Green E/W</button><button class="secondary" data-command="RETURN_TO_AUTOMATIC">Return to Automatic</button></div><button class="secondary" id="ack" style="margin-top:10px">Send ACK for pending command</button></article>
        <article class="panel"><h2>Simulation</h2><form id="sim"><label>event<select name="event_type"><option value="VEHICLE_ARRIVED">arrival</option><option value="VEHICLE_CLEARED">clear</option></select></label><label>vehicle type<select name="vehicle_type"><option>CAR</option><option>TRUCK</option><option>BUS</option><option>MOTORCYCLE</option><option>EMERGENCY</option></select></label><label>direction<select name="direction"><option>NORTH</option><option>SOUTH</option><option>EAST</option><option>WEST</option></select></label><label>vehicle id<input name="vehicle_id" value="demo-1"></label><label>controller<select id="device"><option>ONLINE</option><option>OFFLINE</option></select></label><button>Send sensor event</button></form></article>
        <article class="panel"><h2>Recent activity</h2><ul class="activity" id="history"></ul></article>
    </section>
</main>
<script>
const junctionId='A', api='/api'; let current=null;
const $=id=>document.getElementById(id);
function showError(message){$('error').textContent=message;$('error').style.display='block'}
function clearError(){$('error').style.display='none'}
async function request(path, options={}){const response=await fetch(api+path,{headers:{'Content-Type':'application/json','Accept':'application/json'},...options});let body={};try{body=await response.json()}catch(e){}if(!response.ok)throw new Error(body.error?.message||`Request failed (${response.status})`);return body}
function render(data){current=data;$('title').textContent=`${data.name||'Junction'} · ${data.id}`;$('mode').textContent=data.mode;$('mode').className='badge '+(data.mode==='DEGRADED'?'warn':'');$('phase').textContent=data.phase||'ALL_RED';$('controller').textContent=data.controller_status;$('pending').textContent=data.pending_command?.command_id||'none';$('alerts').textContent=data.alerts?.join(', ')||'none';$('emergency').textContent=data.emergency?.active?'Emergency active: '+data.emergency.active.vehicle_id:'';$('manual').textContent=data.manual?'Manual override: '+data.manual.direction:'';$('signals').innerHTML=Object.entries(data.actual_signals||{}).map(([direction,actual])=>{const desired=data.desired_signals?.[direction]||'UNKNOWN';return `<div class="signal ${actual!==desired?'mismatch':''}"><span class="lamp ${actual}"></span><div><strong>${direction}</strong><small>actual ${actual} · desired ${desired}</small></div></div>`}).join('');$('queues').innerHTML=Object.entries(data.queues||{}).map(([direction,count])=>`<div class="stat"><strong>${count}</strong><span>${direction} queue</span></div>`).join('');$('updated').textContent='Updated '+new Date().toLocaleTimeString()}
function renderHistory(items){$('history').innerHTML=items.map(item=>`<li><time>${item.created_at?new Date(item.created_at).toLocaleTimeString():''}</time><strong>${item.type}</strong><br>${item.payload?.outcome||item.payload?.status||''}</li>`).join('')||'<li>No activity yet.</li>'}
async function poll(){try{const [status,history]=await Promise.all([request(`/junctions/${junctionId}/status`),request(`/junctions/${junctionId}/history?limit=50`)]);render(status.data);renderHistory(history.data);clearError()}catch(error){showError('Backend unavailable or returned an error: '+error.message)}}
// Polling keeps the dashboard simple and robust while providing sufficient 2s freshness for this operator view.
setInterval(poll,2000);poll();
document.querySelectorAll('[data-command]').forEach(button=>button.onclick=async()=>{try{await request(`/junctions/${junctionId}/commands`,{method:'POST',body:JSON.stringify({command:button.dataset.command})});await poll()}catch(error){showError(error.message)}});
$('ack').onclick=async()=>{if(!current?.pending_command?.command_id)return showError('There is no pending command to acknowledge.');try{await request('/controller-events',{method:'POST',body:JSON.stringify({junction_id:junctionId,event_type:'ACK',command_id:current.pending_command.command_id,actual_signals:current.pending_command.desired_signals})});await poll()}catch(error){showError(error.message)}};
$('sim').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);const eventType=form.get('event_type');try{await request('/sensor-events',{method:'POST',body:JSON.stringify({event_id:crypto.randomUUID(),junction_id:junctionId,direction:form.get('direction'),vehicle_type:form.get('vehicle_type'),event_type:eventType,vehicle_id:form.get('vehicle_id'),sequence_no:Date.now(),occurred_at:new Date().toISOString()})});await request('/controller-events',{method:'POST',body:JSON.stringify({junction_id:junctionId,event_type:form.get('controller')})});await poll()}catch(error){showError(error.message)}};
</script>
</body>
</html>
